import os
import msal


def get_client(config=None):
    config = config or {}
    client_id = config.get('client_id', os.getenv('CLIENT_ID'))
    tenant_id = config.get('tenant_id', os.getenv('TENANT_ID'))
    client_secret = config.get('client_secret', os.getenv('CLIENT_SECRET'))
    return msal.ConfidentialClientApplication(
        client_id, authority=f"https://login.microsoftonline.com/{tenant_id}",
        client_credential=client_secret)

from typing import Dict, Any


def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'email': payload['email'],
        'password': payload['password']
    }

import re


def moderate_profile_text(text):
    if re.search(r'\b(badword1|badword2)\b', text, re.IGNORECASE):
        raise ValueError('Profile text contains inappropriate content')
    return text

import json


def summarize_onboarding_state(state):
    return json.dumps(state, indent=2)
